static int scsi_disk_emulate_command(SCSIDiskReq *r, uint8_t *outbuf)

{

    SCSIRequest *req = &r->req;

    SCSIDiskState *s = DO_UPCAST(SCSIDiskState, qdev, req->dev);

    uint64_t nb_sectors;

    int buflen = 0;

    int ret;



    switch (req->cmd.buf[0]) {

    case TEST_UNIT_READY:

        if (!bdrv_is_inserted(s->bs))

            goto not_ready;

        break;

    case REQUEST_SENSE:

        if (req->cmd.xfer < 4)

            goto illegal_request;

        buflen = scsi_device_get_sense(&s->qdev, outbuf, req->cmd.xfer,

                                       (req->cmd.buf[1] & 1) == 0);

        break;

    case INQUIRY:

        buflen = scsi_disk_emulate_inquiry(req, outbuf);

        if (buflen < 0)

            goto illegal_request;

        break;

    case MODE_SENSE:

    case MODE_SENSE_10:

        buflen = scsi_disk_emulate_mode_sense(req, outbuf);

        if (buflen < 0)

            goto illegal_request;

        break;

    case READ_TOC:

        buflen = scsi_disk_emulate_read_toc(req, outbuf);

        if (buflen < 0)

            goto illegal_request;

        break;

    case RESERVE:

        if (req->cmd.buf[1] & 1)

            goto illegal_request;

        break;

    case RESERVE_10:

        if (req->cmd.buf[1] & 3)

            goto illegal_request;

        break;

    case RELEASE:

        if (req->cmd.buf[1] & 1)

            goto illegal_request;

        break;

    case RELEASE_10:

        if (req->cmd.buf[1] & 3)

            goto illegal_request;

        break;

    case START_STOP:

        if (s->qdev.type == TYPE_ROM && (req->cmd.buf[4] & 2)) {

            /* load/eject medium */

            bdrv_eject(s->bs, !(req->cmd.buf[4] & 1));

        }

        break;

    case ALLOW_MEDIUM_REMOVAL:

        bdrv_set_locked(s->bs, req->cmd.buf[4] & 1);

        break;

    case READ_CAPACITY_10:

        /* The normal LEN field for this command is zero.  */

        memset(outbuf, 0, 8);

        bdrv_get_geometry(s->bs, &nb_sectors);

        if (!nb_sectors)

            goto not_ready;

        nb_sectors /= s->cluster_size;

        /* Returned value is the address of the last sector.  */

        nb_sectors--;

        /* Remember the new size for read/write sanity checking. */

        s->max_lba = nb_sectors;

        /* Clip to 2TB, instead of returning capacity modulo 2TB. */

        if (nb_sectors > UINT32_MAX)

            nb_sectors = UINT32_MAX;

        outbuf[0] = (nb_sectors >> 24) & 0xff;

        outbuf[1] = (nb_sectors >> 16) & 0xff;

        outbuf[2] = (nb_sectors >> 8) & 0xff;

        outbuf[3] = nb_sectors & 0xff;

        outbuf[4] = 0;

        outbuf[5] = 0;

        outbuf[6] = s->cluster_size * 2;

        outbuf[7] = 0;

        buflen = 8;

        break;

    case SYNCHRONIZE_CACHE:

        ret = bdrv_flush(s->bs);

        if (ret < 0) {

            if (scsi_handle_rw_error(r, -ret, SCSI_REQ_STATUS_RETRY_FLUSH)) {

                return -1;

            }

        }

        break;

    case GET_CONFIGURATION:

        memset(outbuf, 0, 8);

        /* ??? This should probably return much more information.  For now

           just return the basic header indicating the CD-ROM profile.  */

        outbuf[7] = 8; // CD-ROM

        buflen = 8;

        break;

    case SERVICE_ACTION_IN:

        /* Service Action In subcommands. */

        if ((req->cmd.buf[1] & 31) == 0x10) {

            DPRINTF("SAI READ CAPACITY(16)\n");

            memset(outbuf, 0, req->cmd.xfer);

            bdrv_get_geometry(s->bs, &nb_sectors);

            if (!nb_sectors)

                goto not_ready;

            nb_sectors /= s->cluster_size;

            /* Returned value is the address of the last sector.  */

            nb_sectors--;

            /* Remember the new size for read/write sanity checking. */

            s->max_lba = nb_sectors;

            outbuf[0] = (nb_sectors >> 56) & 0xff;

            outbuf[1] = (nb_sectors >> 48) & 0xff;

            outbuf[2] = (nb_sectors >> 40) & 0xff;

            outbuf[3] = (nb_sectors >> 32) & 0xff;

            outbuf[4] = (nb_sectors >> 24) & 0xff;

            outbuf[5] = (nb_sectors >> 16) & 0xff;

            outbuf[6] = (nb_sectors >> 8) & 0xff;

            outbuf[7] = nb_sectors & 0xff;

            outbuf[8] = 0;

            outbuf[9] = 0;

            outbuf[10] = s->cluster_size * 2;

            outbuf[11] = 0;

            outbuf[12] = 0;

            outbuf[13] = get_physical_block_exp(&s->qdev.conf);



            /* set TPE bit if the format supports discard */

            if (s->qdev.conf.discard_granularity) {

                outbuf[14] = 0x80;

            }



            /* Protection, exponent and lowest lba field left blank. */

            buflen = req->cmd.xfer;

            break;

        }

        DPRINTF("Unsupported Service Action In\n");

        goto illegal_request;

    case REPORT_LUNS:

        if (req->cmd.xfer < 16)

            goto illegal_request;

        memset(outbuf, 0, 16);

        outbuf[3] = 8;

        buflen = 16;

        break;

    case VERIFY_10:

        break;

    default:

        scsi_check_condition(r, SENSE_CODE(INVALID_OPCODE));

        return -1;

    }

    return buflen;



not_ready:

    if (!bdrv_is_inserted(s->bs)) {

        scsi_check_condition(r, SENSE_CODE(NO_MEDIUM));

    } else {

        scsi_check_condition(r, SENSE_CODE(LUN_NOT_READY));

    }

    return -1;



illegal_request:

    scsi_check_condition(r, SENSE_CODE(INVALID_FIELD));

    return -1;

}

static void flush_queued_work(CPUState *cpu)

{

    struct qemu_work_item *wi;



    if (cpu->queued_work_first == NULL) {

        return;

    }



    while ((wi = cpu->queued_work_first)) {

        cpu->queued_work_first = wi->next;

        wi->func(wi->data);

        wi->done = true;

        if (wi->free) {

            g_free(wi);

        }

    }

    cpu->queued_work_last = NULL;

    qemu_cond_broadcast(&qemu_work_cond);

}

static int validate_guest_space(unsigned long guest_base,

                                unsigned long guest_size)

{

    unsigned long real_start, test_page_addr;



    /* We need to check that we can force a fault on access to the

     * commpage at 0xffff0fxx

     */

    test_page_addr = guest_base + (0xffff0f00 & qemu_host_page_mask);



    /* If the commpage lies within the already allocated guest space,

     * then there is no way we can allocate it.

     */

    if (test_page_addr >= guest_base

        && test_page_addr <= (guest_base + guest_size)) {

        return -1;

    }



    /* Note it needs to be writeable to let us initialise it */

    real_start = (unsigned long)

                 mmap((void *)test_page_addr, qemu_host_page_size,

                     PROT_READ | PROT_WRITE,

                     MAP_ANONYMOUS | MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);



    /* If we can't map it then try another address */

    if (real_start == -1ul) {

        return 0;

    }



    if (real_start != test_page_addr) {

        /* OS didn't put the page where we asked - unmap and reject */

        munmap((void *)real_start, qemu_host_page_size);

        return 0;

    }



    /* Leave the page mapped

     * Populate it (mmap should have left it all 0'd)

     */



    /* Kernel helper versions */

    __put_user(5, (uint32_t *)g2h(0xffff0ffcul));



    /* Now it's populated make it RO */

    if (mprotect((void *)test_page_addr, qemu_host_page_size, PROT_READ)) {

        perror("Protecting guest commpage");

        exit(-1);

    }



    return 1; /* All good */

}

long do_sigreturn(CPUCRISState *env)

{

	struct target_signal_frame *frame;

	abi_ulong frame_addr;

	target_sigset_t target_set;

	sigset_t set;

	int i;



	frame_addr = env->regs[R_SP];

	/* Make sure the guest isn't playing games.  */

	if (!lock_user_struct(VERIFY_WRITE, frame, frame_addr, 1))

		goto badframe;



	/* Restore blocked signals */

	if (__get_user(target_set.sig[0], &frame->sc.oldmask))

		goto badframe;

	for(i = 1; i < TARGET_NSIG_WORDS; i++) {

		if (__get_user(target_set.sig[i], &frame->extramask[i - 1]))

			goto badframe;

	}

	target_to_host_sigset_internal(&set, &target_set);

        do_sigprocmask(SIG_SETMASK, &set, NULL);



	restore_sigcontext(&frame->sc, env);

	unlock_user_struct(frame, frame_addr, 0);

	return env->regs[10];

  badframe:

	unlock_user_struct(frame, frame_addr, 0);

	force_sig(TARGET_SIGSEGV);

}

static void usbredir_interrupt_packet(void *priv, uint32_t id,

    struct usb_redir_interrupt_packet_header *interrupt_packet,

    uint8_t *data, int data_len)

{

    USBRedirDevice *dev = priv;

    uint8_t ep = interrupt_packet->endpoint;



    DPRINTF("interrupt-in status %d ep %02X len %d id %u\n",

            interrupt_packet->status, ep, data_len, id);



    if (dev->endpoint[EP2I(ep)].type != USB_ENDPOINT_XFER_INT) {

        ERROR("received int packet for non interrupt endpoint %02X\n", ep);

        free(data);

        return;

    }



    if (ep & USB_DIR_IN) {

        if (dev->endpoint[EP2I(ep)].interrupt_started == 0) {

            DPRINTF("received int packet while not started ep %02X\n", ep);

            free(data);

            return;

        }



        /* bufp_alloc also adds the packet to the ep queue */

        bufp_alloc(dev, data, data_len, interrupt_packet->status, ep);

    } else {

        int len = interrupt_packet->length;



        AsyncURB *aurb = async_find(dev, id);

        if (!aurb) {

            return;

        }



        if (aurb->interrupt_packet.endpoint != interrupt_packet->endpoint) {

            ERROR("return int packet mismatch, please report this!\n");

            len = USB_RET_NAK;

        }



        if (aurb->packet) {

            aurb->packet->len = usbredir_handle_status(dev,

                                               interrupt_packet->status, len);

            usb_packet_complete(&dev->dev, aurb->packet);

        }

        async_free(dev, aurb);

    }

}

void mpeg1_encode_mb(MpegEncContext *s,

                     DCTELEM block[6][64],

                     int motion_x, int motion_y)

{

    int i, cbp;

    const int mb_x = s->mb_x;

    const int mb_y = s->mb_y;

    const int first_mb= mb_x == s->resync_mb_x && mb_y == s->resync_mb_y;



    /* compute cbp */

    cbp = 0;

    for(i=0;i<6;i++) {

        if (s->block_last_index[i] >= 0)

            cbp |= 1 << (5 - i);

    }



    if (cbp == 0 && !first_mb && (mb_x != s->mb_width - 1 || (mb_y != s->mb_height - 1 && s->codec_id == CODEC_ID_MPEG1VIDEO)) && 

        ((s->pict_type == P_TYPE && s->mv_type == MV_TYPE_16X16 && (motion_x | motion_y) == 0) ||

        (s->pict_type == B_TYPE && s->mv_dir == s->last_mv_dir && (((s->mv_dir & MV_DIR_FORWARD) ? ((s->mv[0][0][0] - s->last_mv[0][0][0])|(s->mv[0][0][1] - s->last_mv[0][0][1])) : 0) |

        ((s->mv_dir & MV_DIR_BACKWARD) ? ((s->mv[1][0][0] - s->last_mv[1][0][0])|(s->mv[1][0][1] - s->last_mv[1][0][1])) : 0)) == 0))) {

        s->mb_skip_run++;

        s->qscale -= s->dquant;

        s->skip_count++;

        s->misc_bits++;

        s->last_bits++;

        if(s->pict_type == P_TYPE){

            s->last_mv[0][1][0]= s->last_mv[0][0][0]= 

            s->last_mv[0][1][1]= s->last_mv[0][0][1]= 0;

        }

    } else {

        if(first_mb){

            assert(s->mb_skip_run == 0);

            encode_mb_skip_run(s, s->mb_x);

        }else{

            encode_mb_skip_run(s, s->mb_skip_run);

        }



        if (s->pict_type == I_TYPE) {

            if(s->dquant && cbp){

                put_mb_modes(s, 2, 1, 0, 0); /* macroblock_type : macroblock_quant = 1 */

                put_bits(&s->pb, 5, s->qscale);

            }else{

                put_mb_modes(s, 1, 1, 0, 0); /* macroblock_type : macroblock_quant = 0 */

                s->qscale -= s->dquant;

            }

            s->misc_bits+= get_bits_diff(s);

            s->i_count++;

        } else if (s->mb_intra) {

            if(s->dquant && cbp){

                put_mb_modes(s, 6, 0x01, 0, 0);

                put_bits(&s->pb, 5, s->qscale);

            }else{

                put_mb_modes(s, 5, 0x03, 0, 0);

                s->qscale -= s->dquant;

            }

            s->misc_bits+= get_bits_diff(s);

            s->i_count++;

            memset(s->last_mv, 0, sizeof(s->last_mv));

        } else if (s->pict_type == P_TYPE) { 

            if(s->mv_type == MV_TYPE_16X16){

                if (cbp != 0) {

                    if ((motion_x|motion_y) == 0) {

                        if(s->dquant){

                            put_mb_modes(s, 5, 1, 0, 0); /* macroblock_pattern & quant */

                            put_bits(&s->pb, 5, s->qscale);

                        }else{

                            put_mb_modes(s, 2, 1, 0, 0); /* macroblock_pattern only */

                        }

                        s->misc_bits+= get_bits_diff(s);

                    } else {

                        if(s->dquant){

                            put_mb_modes(s, 5, 2, 1, 0); /* motion + cbp */

                            put_bits(&s->pb, 5, s->qscale);

                        }else{

                            put_mb_modes(s, 1, 1, 1, 0); /* motion + cbp */

                        }

                        s->misc_bits+= get_bits_diff(s);

                        mpeg1_encode_motion(s, motion_x - s->last_mv[0][0][0], s->f_code);    // RAL: f_code parameter added

                        mpeg1_encode_motion(s, motion_y - s->last_mv[0][0][1], s->f_code);    // RAL: f_code parameter added

                        s->mv_bits+= get_bits_diff(s);

                    }

                } else {

                    put_bits(&s->pb, 3, 1); /* motion only */

                    if (!s->frame_pred_frame_dct)

                        put_bits(&s->pb, 2, 2); /* motion_type: frame */

                    s->misc_bits+= get_bits_diff(s);

                    mpeg1_encode_motion(s, motion_x - s->last_mv[0][0][0], s->f_code);    // RAL: f_code parameter added

                    mpeg1_encode_motion(s, motion_y - s->last_mv[0][0][1], s->f_code);    // RAL: f_code parameter added

                    s->qscale -= s->dquant;

                    s->mv_bits+= get_bits_diff(s);

                }

                s->last_mv[0][1][0]= s->last_mv[0][0][0]= motion_x;

                s->last_mv[0][1][1]= s->last_mv[0][0][1]= motion_y;

            }else{

                assert(!s->frame_pred_frame_dct && s->mv_type == MV_TYPE_FIELD);



                if (cbp) {

                    if(s->dquant){

                        put_mb_modes(s, 5, 2, 1, 1); /* motion + cbp */

                        put_bits(&s->pb, 5, s->qscale);

                    }else{

                        put_mb_modes(s, 1, 1, 1, 1); /* motion + cbp */

                    }

                } else {

                    put_bits(&s->pb, 3, 1); /* motion only */

                    put_bits(&s->pb, 2, 1); /* motion_type: field */

                    s->qscale -= s->dquant;

                }

                s->misc_bits+= get_bits_diff(s);

                for(i=0; i<2; i++){

                    put_bits(&s->pb, 1, s->field_select[0][i]);

                    mpeg1_encode_motion(s, s->mv[0][i][0] -  s->last_mv[0][i][0]    , s->f_code);

                    mpeg1_encode_motion(s, s->mv[0][i][1] - (s->last_mv[0][i][1]>>1), s->f_code);

                    s->last_mv[0][i][0]=   s->mv[0][i][0];

                    s->last_mv[0][i][1]= 2*s->mv[0][i][1];

                }

                s->mv_bits+= get_bits_diff(s);

            }

            if(cbp)

                put_bits(&s->pb, mbPatTable[cbp - 1][1], mbPatTable[cbp - 1][0]);

            s->f_count++;

        } else{  

            static const int mb_type_len[4]={0,3,4,2}; //bak,for,bi



            if(s->mv_type == MV_TYPE_16X16){

                if (cbp){    // With coded bloc pattern

                    if (s->dquant) {

                        if(s->mv_dir == MV_DIR_FORWARD)

                            put_mb_modes(s, 6, 3, 1, 0);

                        else

                            put_mb_modes(s, mb_type_len[s->mv_dir]+3, 2, 1, 0);

                        put_bits(&s->pb, 5, s->qscale);

                    } else {

                        put_mb_modes(s, mb_type_len[s->mv_dir], 3, 1, 0);

                    }

                }else{    // No coded bloc pattern

                    put_bits(&s->pb, mb_type_len[s->mv_dir], 2);

                    if (!s->frame_pred_frame_dct)

                        put_bits(&s->pb, 2, 2); /* motion_type: frame */

                    s->qscale -= s->dquant;

                }

                s->misc_bits += get_bits_diff(s);

                if (s->mv_dir&MV_DIR_FORWARD){

                    mpeg1_encode_motion(s, s->mv[0][0][0] - s->last_mv[0][0][0], s->f_code); 

                    mpeg1_encode_motion(s, s->mv[0][0][1] - s->last_mv[0][0][1], s->f_code); 

                    s->last_mv[0][0][0]=s->last_mv[0][1][0]= s->mv[0][0][0];

                    s->last_mv[0][0][1]=s->last_mv[0][1][1]= s->mv[0][0][1];

                    s->f_count++;

                }

                if (s->mv_dir&MV_DIR_BACKWARD){

                    mpeg1_encode_motion(s, s->mv[1][0][0] - s->last_mv[1][0][0], s->b_code); 

                    mpeg1_encode_motion(s, s->mv[1][0][1] - s->last_mv[1][0][1], s->b_code); 

                    s->last_mv[1][0][0]=s->last_mv[1][1][0]= s->mv[1][0][0];

                    s->last_mv[1][0][1]=s->last_mv[1][1][1]= s->mv[1][0][1];

                    s->b_count++;

                }

            }else{

                assert(s->mv_type == MV_TYPE_FIELD);

                assert(!s->frame_pred_frame_dct);

                if (cbp){    // With coded bloc pattern

                    if (s->dquant) {

                        if(s->mv_dir == MV_DIR_FORWARD)

                            put_mb_modes(s, 6, 3, 1, 1);

                        else

                            put_mb_modes(s, mb_type_len[s->mv_dir]+3, 2, 1, 1);

                        put_bits(&s->pb, 5, s->qscale);

                    } else {

                        put_mb_modes(s, mb_type_len[s->mv_dir], 3, 1, 1);

                    }

                }else{    // No coded bloc pattern

                    put_bits(&s->pb, mb_type_len[s->mv_dir], 2);

                    put_bits(&s->pb, 2, 1); /* motion_type: field */

                    s->qscale -= s->dquant;

                }

                s->misc_bits += get_bits_diff(s);

                if (s->mv_dir&MV_DIR_FORWARD){

                    for(i=0; i<2; i++){

                        put_bits(&s->pb, 1, s->field_select[0][i]);

                        mpeg1_encode_motion(s, s->mv[0][i][0] -  s->last_mv[0][i][0]    , s->f_code);

                        mpeg1_encode_motion(s, s->mv[0][i][1] - (s->last_mv[0][i][1]>>1), s->f_code);

                        s->last_mv[0][i][0]=   s->mv[0][i][0];

                        s->last_mv[0][i][1]= 2*s->mv[0][i][1];

                    }

                    s->f_count++;

                }

                if (s->mv_dir&MV_DIR_BACKWARD){

                    for(i=0; i<2; i++){

                        put_bits(&s->pb, 1, s->field_select[1][i]);

                        mpeg1_encode_motion(s, s->mv[1][i][0] -  s->last_mv[1][i][0]    , s->b_code);

                        mpeg1_encode_motion(s, s->mv[1][i][1] - (s->last_mv[1][i][1]>>1), s->b_code);

                        s->last_mv[1][i][0]=   s->mv[1][i][0];

                        s->last_mv[1][i][1]= 2*s->mv[1][i][1];

                    }

                    s->b_count++;

                }

            }

            s->mv_bits += get_bits_diff(s);

            if(cbp)

                put_bits(&s->pb, mbPatTable[cbp - 1][1], mbPatTable[cbp - 1][0]);

        }

        for(i=0;i<6;i++) {

            if (cbp & (1 << (5 - i))) {

                mpeg1_encode_block(s, block[i], i);

            }

        }

        s->mb_skip_run = 0;

        if(s->mb_intra)

            s->i_tex_bits+= get_bits_diff(s);

        else

            s->p_tex_bits+= get_bits_diff(s);

    }

}

static void virtio_ccw_device_realize(VirtioCcwDevice *dev, Error **errp)

{

    unsigned int cssid = 0;

    unsigned int ssid = 0;

    unsigned int schid;

    unsigned int devno;

    bool have_devno = false;

    bool found = false;

    SubchDev *sch;

    int num;

    DeviceState *parent = DEVICE(dev);

    Error *err = NULL;

    VirtIOCCWDeviceClass *k = VIRTIO_CCW_DEVICE_GET_CLASS(dev);

    VirtIODevice *vdev;



    sch = g_malloc0(sizeof(SubchDev));



    sch->driver_data = dev;

    dev->sch = sch;



    dev->indicators = NULL;



    /* Initialize subchannel structure. */

    sch->channel_prog = 0x0;

    sch->last_cmd_valid = false;

    sch->thinint_active = false;

    /*

     * Use a device number if provided. Otherwise, fall back to subchannel

     * number.

     */

    if (dev->bus_id) {

        num = sscanf(dev->bus_id, "%x.%x.%04x", &cssid, &ssid, &devno);

        if (num == 3) {

            if ((cssid > MAX_CSSID) || (ssid > MAX_SSID)) {

                error_setg(errp, "Invalid cssid or ssid: cssid %x, ssid %x",

                           cssid, ssid);

                goto out_err;

            }

            /* Enforce use of virtual cssid. */

            if (cssid != VIRTUAL_CSSID) {

                error_setg(errp, "cssid %x not valid for virtio devices",

                           cssid);

                goto out_err;

            }

            if (css_devno_used(cssid, ssid, devno)) {

                error_setg(errp, "Device %x.%x.%04x already exists",

                           cssid, ssid, devno);

                goto out_err;

            }

            sch->cssid = cssid;

            sch->ssid = ssid;

            sch->devno = devno;

            have_devno = true;

        } else {

            error_setg(errp, "Malformed devno parameter '%s'", dev->bus_id);

            goto out_err;

        }

    }



    /* Find the next free id. */

    if (have_devno) {

        for (schid = 0; schid <= MAX_SCHID; schid++) {

            if (!css_find_subch(1, cssid, ssid, schid)) {

                sch->schid = schid;

                css_subch_assign(cssid, ssid, schid, devno, sch);

                found = true;

                break;

            }

        }

        if (!found) {

            error_setg(errp, "No free subchannel found for %x.%x.%04x",

                       cssid, ssid, devno);

            goto out_err;

        }

        trace_virtio_ccw_new_device(cssid, ssid, schid, devno,

                                    "user-configured");

    } else {

        cssid = VIRTUAL_CSSID;

        for (ssid = 0; ssid <= MAX_SSID; ssid++) {

            for (schid = 0; schid <= MAX_SCHID; schid++) {

                if (!css_find_subch(1, cssid, ssid, schid)) {

                    sch->cssid = cssid;

                    sch->ssid = ssid;

                    sch->schid = schid;

                    devno = schid;

                    /*

                     * If the devno is already taken, look further in this

                     * subchannel set.

                     */

                    while (css_devno_used(cssid, ssid, devno)) {

                        if (devno == MAX_SCHID) {

                            devno = 0;

                        } else if (devno == schid - 1) {

                            error_setg(errp, "No free devno found");

                            goto out_err;

                        } else {

                            devno++;

                        }

                    }

                    sch->devno = devno;

                    css_subch_assign(cssid, ssid, schid, devno, sch);

                    found = true;

                    break;

                }

            }

            if (found) {

                break;

            }

        }

        if (!found) {

            error_setg(errp, "Virtual channel subsystem is full!");

            goto out_err;

        }

        trace_virtio_ccw_new_device(cssid, ssid, schid, devno,

                                    "auto-configured");

    }



    /* Build initial schib. */

    css_sch_build_virtual_schib(sch, 0, VIRTIO_CCW_CHPID_TYPE);



    sch->ccw_cb = virtio_ccw_cb;



    /* Build senseid data. */

    memset(&sch->id, 0, sizeof(SenseId));

    sch->id.reserved = 0xff;

    sch->id.cu_type = VIRTIO_CCW_CU_TYPE;



    if (k->realize) {

        k->realize(dev, &err);

    }

    if (err) {

        error_propagate(errp, err);

        css_subch_assign(cssid, ssid, schid, devno, NULL);

        goto out_err;

    }



    /* device_id is only set after vdev has been realized */

    vdev = virtio_ccw_get_vdev(sch);

    sch->id.cu_model = vdev->device_id;



    /* Only the first 32 feature bits are used. */

    dev->host_features[0] = virtio_bus_get_vdev_features(&dev->bus,

                                                         dev->host_features[0]);



    virtio_add_feature(&dev->host_features[0], VIRTIO_F_NOTIFY_ON_EMPTY);

    virtio_add_feature(&dev->host_features[0], VIRTIO_F_BAD_FEATURE);



    css_generate_sch_crws(sch->cssid, sch->ssid, sch->schid,

                          parent->hotplugged, 1);

    return;



out_err:

    dev->sch = NULL;

    g_free(sch);

}

