}

static void acpi_dsdt_add_pci(Aml *scope, const MemMapEntry *memmap,

                              uint32_t irq, bool use_highmem)

{

    Aml *method, *crs, *ifctx, *UUID, *ifctx1, *elsectx, *buf;

    int i, bus_no;

    hwaddr base_mmio = memmap[VIRT_PCIE_MMIO].base;

    hwaddr size_mmio = memmap[VIRT_PCIE_MMIO].size;

    hwaddr base_pio = memmap[VIRT_PCIE_PIO].base;

    hwaddr size_pio = memmap[VIRT_PCIE_PIO].size;

    hwaddr base_ecam = memmap[VIRT_PCIE_ECAM].base;

    hwaddr size_ecam = memmap[VIRT_PCIE_ECAM].size;

    int nr_pcie_buses = size_ecam / PCIE_MMCFG_SIZE_MIN;



    Aml *dev = aml_device("%s", "PCI0");

    aml_append(dev, aml_name_decl("_HID", aml_string("PNP0A08")));

    aml_append(dev, aml_name_decl("_CID", aml_string("PNP0A03")));

    aml_append(dev, aml_name_decl("_SEG", aml_int(0)));

    aml_append(dev, aml_name_decl("_BBN", aml_int(0)));

    aml_append(dev, aml_name_decl("_ADR", aml_int(0)));

    aml_append(dev, aml_name_decl("_UID", aml_string("PCI0")));

    aml_append(dev, aml_name_decl("_STR", aml_unicode("PCIe 0 Device")));

    aml_append(dev, aml_name_decl("_CCA", aml_int(1)));



    /* Declare the PCI Routing Table. */

    Aml *rt_pkg = aml_package(nr_pcie_buses * PCI_NUM_PINS);

    for (bus_no = 0; bus_no < nr_pcie_buses; bus_no++) {

        for (i = 0; i < PCI_NUM_PINS; i++) {

            int gsi = (i + bus_no) % PCI_NUM_PINS;

            Aml *pkg = aml_package(4);

            aml_append(pkg, aml_int((bus_no << 16) | 0xFFFF));

            aml_append(pkg, aml_int(i));

            aml_append(pkg, aml_name("GSI%d", gsi));

            aml_append(pkg, aml_int(0));

            aml_append(rt_pkg, pkg);

        }

    }

    aml_append(dev, aml_name_decl("_PRT", rt_pkg));



    /* Create GSI link device */

    for (i = 0; i < PCI_NUM_PINS; i++) {

        uint32_t irqs =  irq + i;

        Aml *dev_gsi = aml_device("GSI%d", i);

        aml_append(dev_gsi, aml_name_decl("_HID", aml_string("PNP0C0F")));

        aml_append(dev_gsi, aml_name_decl("_UID", aml_int(0)));

        crs = aml_resource_template();

        aml_append(crs,

                   aml_interrupt(AML_CONSUMER, AML_LEVEL, AML_ACTIVE_HIGH,

                                 AML_EXCLUSIVE, &irqs, 1));

        aml_append(dev_gsi, aml_name_decl("_PRS", crs));

        crs = aml_resource_template();

        aml_append(crs,

                   aml_interrupt(AML_CONSUMER, AML_LEVEL, AML_ACTIVE_HIGH,

                                 AML_EXCLUSIVE, &irqs, 1));

        aml_append(dev_gsi, aml_name_decl("_CRS", crs));

        method = aml_method("_SRS", 1, AML_NOTSERIALIZED);

        aml_append(dev_gsi, method);

        aml_append(dev, dev_gsi);

    }



    method = aml_method("_CBA", 0, AML_NOTSERIALIZED);

    aml_append(method, aml_return(aml_int(base_ecam)));

    aml_append(dev, method);



    method = aml_method("_CRS", 0, AML_NOTSERIALIZED);

    Aml *rbuf = aml_resource_template();

    aml_append(rbuf,

        aml_word_bus_number(AML_MIN_FIXED, AML_MAX_FIXED, AML_POS_DECODE,

                            0x0000, 0x0000, nr_pcie_buses - 1, 0x0000,

                            nr_pcie_buses));

    aml_append(rbuf,

        aml_dword_memory(AML_POS_DECODE, AML_MIN_FIXED, AML_MAX_FIXED,

                         AML_NON_CACHEABLE, AML_READ_WRITE, 0x0000, base_mmio,

                         base_mmio + size_mmio - 1, 0x0000, size_mmio));

    aml_append(rbuf,

        aml_dword_io(AML_MIN_FIXED, AML_MAX_FIXED, AML_POS_DECODE,

                     AML_ENTIRE_RANGE, 0x0000, 0x0000, size_pio - 1, base_pio,

                     size_pio));



    if (use_highmem) {

        hwaddr base_mmio_high = memmap[VIRT_PCIE_MMIO_HIGH].base;

        hwaddr size_mmio_high = memmap[VIRT_PCIE_MMIO_HIGH].size;



        aml_append(rbuf,

            aml_qword_memory(AML_POS_DECODE, AML_MIN_FIXED, AML_MAX_FIXED,

                             AML_NON_CACHEABLE, AML_READ_WRITE, 0x0000,

                             base_mmio_high, base_mmio_high, 0x0000,

                             size_mmio_high));

    }



    aml_append(method, aml_name_decl("RBUF", rbuf));

    aml_append(method, aml_return(rbuf));

    aml_append(dev, method);



    /* Declare an _OSC (OS Control Handoff) method */

    aml_append(dev, aml_name_decl("SUPP", aml_int(0)));

    aml_append(dev, aml_name_decl("CTRL", aml_int(0)));

    method = aml_method("_OSC", 4, AML_NOTSERIALIZED);

    aml_append(method,

        aml_create_dword_field(aml_arg(3), aml_int(0), "CDW1"));



    /* PCI Firmware Specification 3.0

     * 4.5.1. _OSC Interface for PCI Host Bridge Devices

     * The _OSC interface for a PCI/PCI-X/PCI Express hierarchy is

     * identified by the Universal Unique IDentifier (UUID)

     * 33DB4D5B-1FF7-401C-9657-7441C03DD766

     */

    UUID = aml_touuid("33DB4D5B-1FF7-401C-9657-7441C03DD766");

    ifctx = aml_if(aml_equal(aml_arg(0), UUID));

    aml_append(ifctx,

        aml_create_dword_field(aml_arg(3), aml_int(4), "CDW2"));

    aml_append(ifctx,

        aml_create_dword_field(aml_arg(3), aml_int(8), "CDW3"));

    aml_append(ifctx, aml_store(aml_name("CDW2"), aml_name("SUPP")));

    aml_append(ifctx, aml_store(aml_name("CDW3"), aml_name("CTRL")));

    aml_append(ifctx, aml_store(aml_and(aml_name("CTRL"), aml_int(0x1D), NULL),

                                aml_name("CTRL")));



    ifctx1 = aml_if(aml_lnot(aml_equal(aml_arg(1), aml_int(0x1))));

    aml_append(ifctx1, aml_store(aml_or(aml_name("CDW1"), aml_int(0x08), NULL),

                                 aml_name("CDW1")));

    aml_append(ifctx, ifctx1);



    ifctx1 = aml_if(aml_lnot(aml_equal(aml_name("CDW3"), aml_name("CTRL"))));

    aml_append(ifctx1, aml_store(aml_or(aml_name("CDW1"), aml_int(0x10), NULL),

                                 aml_name("CDW1")));

    aml_append(ifctx, ifctx1);



    aml_append(ifctx, aml_store(aml_name("CTRL"), aml_name("CDW3")));

    aml_append(ifctx, aml_return(aml_arg(3)));

    aml_append(method, ifctx);



    elsectx = aml_else();

    aml_append(elsectx, aml_store(aml_or(aml_name("CDW1"), aml_int(4), NULL),

                                  aml_name("CDW1")));

    aml_append(elsectx, aml_return(aml_arg(3)));

    aml_append(method, elsectx);

    aml_append(dev, method);



    method = aml_method("_DSM", 4, AML_NOTSERIALIZED);



    /* PCI Firmware Specification 3.0

     * 4.6.1. _DSM for PCI Express Slot Information

     * The UUID in _DSM in this context is

     * {E5C937D0-3553-4D7A-9117-EA4D19C3434D}

     */

    UUID = aml_touuid("E5C937D0-3553-4D7A-9117-EA4D19C3434D");

    ifctx = aml_if(aml_equal(aml_arg(0), UUID));

    ifctx1 = aml_if(aml_equal(aml_arg(2), aml_int(0)));

    uint8_t byte_list[1] = {1};

    buf = aml_buffer(1, byte_list);

    aml_append(ifctx1, aml_return(buf));

    aml_append(ifctx, ifctx1);

    aml_append(method, ifctx);



    byte_list[0] = 0;

    buf = aml_buffer(1, byte_list);

    aml_append(method, aml_return(buf));

    aml_append(dev, method);



    Aml *dev_rp0 = aml_device("%s", "RP0");

    aml_append(dev_rp0, aml_name_decl("_ADR", aml_int(0)));

    aml_append(dev, dev_rp0);

    aml_append(scope, dev);

}

static int vmdk_parent_open(BlockDriverState *bs)

{

    char *p_name;

    char desc[DESC_SIZE + 1];

    BDRVVmdkState *s = bs->opaque;



    desc[DESC_SIZE] = '\0';

    if (bdrv_pread(bs->file, s->desc_offset, desc, DESC_SIZE) != DESC_SIZE) {

        return -1;

    }



    if ((p_name = strstr(desc,"parentFileNameHint")) != NULL) {

        char *end_name;



        p_name += sizeof("parentFileNameHint") + 1;

        if ((end_name = strchr(p_name,'\"')) == NULL)

            return -1;

        if ((end_name - p_name) > sizeof (bs->backing_file) - 1)

            return -1;



        pstrcpy(bs->backing_file, end_name - p_name + 1, p_name);

    }



    return 0;

}

static MemoryRegionSection address_space_do_translate(AddressSpace *as,

                                                      hwaddr addr,

                                                      hwaddr *xlat,

                                                      hwaddr *plen,

                                                      bool is_write,

                                                      bool is_mmio)

{

    IOMMUTLBEntry iotlb;

    MemoryRegionSection *section;

    MemoryRegion *mr;



    for (;;) {

        AddressSpaceDispatch *d = atomic_rcu_read(&as->dispatch);

        section = address_space_translate_internal(d, addr, &addr, plen, is_mmio);

        mr = section->mr;



        if (!mr->iommu_ops) {

            break;

        }



        iotlb = mr->iommu_ops->translate(mr, addr, is_write);

        addr = ((iotlb.translated_addr & ~iotlb.addr_mask)

                | (addr & iotlb.addr_mask));

        *plen = MIN(*plen, (addr | iotlb.addr_mask) - addr + 1);

        if (!(iotlb.perm & (1 << is_write))) {

            goto translate_fail;

        }



        as = iotlb.target_as;

    }



    *xlat = addr;



    return *section;



translate_fail:

    return (MemoryRegionSection) { .mr = &io_mem_unassigned };

}

static void read_guest_mem(void)

{

    uint32_t *guest_mem;

    gint64 end_time;

    int i, j;

    size_t size;



    g_mutex_lock(data_mutex);



    end_time = g_get_monotonic_time() + 5 * G_TIME_SPAN_SECOND;

    while (!fds_num) {

        if (!_cond_wait_until(data_cond, data_mutex, end_time)) {

            /* timeout has passed */

            g_assert(fds_num);

            break;

        }

    }



    /* check for sanity */

    g_assert_cmpint(fds_num, >, 0);

    g_assert_cmpint(fds_num, ==, memory.nregions);



    /* iterate all regions */

    for (i = 0; i < fds_num; i++) {



        /* We'll check only the region statring at 0x0*/

        if (memory.regions[i].guest_phys_addr != 0x0) {

            continue;

        }



        g_assert_cmpint(memory.regions[i].memory_size, >, 1024);



        size =  memory.regions[i].memory_size + memory.regions[i].mmap_offset;



        guest_mem = mmap(0, size, PROT_READ | PROT_WRITE,

                         MAP_SHARED, fds[i], 0);



        g_assert(guest_mem != MAP_FAILED);

        guest_mem += (memory.regions[i].mmap_offset / sizeof(*guest_mem));



        for (j = 0; j < 256; j++) {

            uint32_t a = readl(memory.regions[i].guest_phys_addr + j*4);

            uint32_t b = guest_mem[j];



            g_assert_cmpint(a, ==, b);

        }



        munmap(guest_mem, memory.regions[i].memory_size);

    }



    g_assert_cmpint(1, ==, 1);

    g_mutex_unlock(data_mutex);

}

static uint64_t qemu_rdma_poll(RDMAContext *rdma, uint64_t *wr_id_out,

                               uint32_t *byte_len)

{

    int ret;

    struct ibv_wc wc;

    uint64_t wr_id;



    ret = ibv_poll_cq(rdma->cq, 1, &wc);



    if (!ret) {

        *wr_id_out = RDMA_WRID_NONE;

        return 0;

    }



    if (ret < 0) {

        fprintf(stderr, "ibv_poll_cq return %d!\n", ret);

        return ret;

    }



    wr_id = wc.wr_id & RDMA_WRID_TYPE_MASK;



    if (wc.status != IBV_WC_SUCCESS) {

        fprintf(stderr, "ibv_poll_cq wc.status=%d %s!\n",

                        wc.status, ibv_wc_status_str(wc.status));

        fprintf(stderr, "ibv_poll_cq wrid=%s!\n", wrid_desc[wr_id]);



        return -1;

    }



    if (rdma->control_ready_expected &&

        (wr_id >= RDMA_WRID_RECV_CONTROL)) {

        DDDPRINTF("completion %s #%" PRId64 " received (%" PRId64 ")"

                  " left %d\n", wrid_desc[RDMA_WRID_RECV_CONTROL],

                  wr_id - RDMA_WRID_RECV_CONTROL, wr_id, rdma->nb_sent);

        rdma->control_ready_expected = 0;

    }



    if (wr_id == RDMA_WRID_RDMA_WRITE) {

        uint64_t chunk =

            (wc.wr_id & RDMA_WRID_CHUNK_MASK) >> RDMA_WRID_CHUNK_SHIFT;

        uint64_t index =

            (wc.wr_id & RDMA_WRID_BLOCK_MASK) >> RDMA_WRID_BLOCK_SHIFT;

        RDMALocalBlock *block = &(rdma->local_ram_blocks.block[index]);



        DDDPRINTF("completions %s (%" PRId64 ") left %d, "

                 "block %" PRIu64 ", chunk: %" PRIu64 " %p %p\n",

                 print_wrid(wr_id), wr_id, rdma->nb_sent, index, chunk,

                 block->local_host_addr, (void *)block->remote_host_addr);



        clear_bit(chunk, block->transit_bitmap);



        if (rdma->nb_sent > 0) {

            rdma->nb_sent--;

        }



        if (!rdma->pin_all) {

            /*

             * FYI: If one wanted to signal a specific chunk to be unregistered

             * using LRU or workload-specific information, this is the function

             * you would call to do so. That chunk would then get asynchronously

             * unregistered later.

             */

#ifdef RDMA_UNREGISTRATION_EXAMPLE

            qemu_rdma_signal_unregister(rdma, index, chunk, wc.wr_id);

#endif

        }

    } else {

        DDDPRINTF("other completion %s (%" PRId64 ") received left %d\n",

            print_wrid(wr_id), wr_id, rdma->nb_sent);

    }



    *wr_id_out = wc.wr_id;

    if (byte_len) {

        *byte_len = wc.byte_len;

    }



    return  0;

}

static int mov_read_ftyp(MOVContext *c, AVIOContext *pb, MOVAtom atom)

{

    uint32_t minor_ver;

    int comp_brand_size;

    char minor_ver_str[11]; /* 32 bit integer -> 10 digits + null */

    char* comp_brands_str;

    uint8_t type[5] = {0};



    avio_read(pb, type, 4);

    if (strcmp(type, "qt  "))

        c->isom = 1;

    av_log(c->fc, AV_LOG_DEBUG, "ISO: File Type Major Brand: %.4s\n",(char *)&type);

    av_dict_set(&c->fc->metadata, "major_brand", type, 0);

    minor_ver = avio_rb32(pb); /* minor version */

    snprintf(minor_ver_str, sizeof(minor_ver_str), "%"PRIu32"", minor_ver);

    av_dict_set(&c->fc->metadata, "minor_version", minor_ver_str, 0);



    comp_brand_size = atom.size - 8;

    if (comp_brand_size < 0)

        return AVERROR_INVALIDDATA;

    comp_brands_str = av_malloc(comp_brand_size + 1); /* Add null terminator */

    if (!comp_brands_str)

        return AVERROR(ENOMEM);

    avio_read(pb, comp_brands_str, comp_brand_size);

    comp_brands_str[comp_brand_size] = 0;

    av_dict_set(&c->fc->metadata, "compatible_brands", comp_brands_str, 0);

    av_freep(&comp_brands_str);



    return 0;

}

static void qpci_pc_config_writew(QPCIBus *bus, int devfn, uint8_t offset, uint16_t value)

{

