        return 0;

    if (index == MAX_PARALLEL_PORTS) {

        fprintf(stderr, "qemu: too many parallel ports\n");

        exit(1);

    }

    snprintf(label, sizeof(label), "parallel%d", index);

    parallel_hds[index] = qemu_chr_new(label, devname, NULL);

