static void curl_readv_bh_cb(void *p)

{

    CURLState *state;

    int running;



    CURLAIOCB *acb = p;

    BDRVCURLState *s = acb->common.bs->opaque;



    qemu_bh_delete(acb->bh);

    acb->bh = NULL;



    size_t start = acb->sector_num * SECTOR_SIZE;

    size_t end;



    // In case we have the requested data already (e.g. read-ahead),

    // we can just call the callback and be done.

    switch (curl_find_buf(s, start, acb->nb_sectors * SECTOR_SIZE, acb)) {

        case FIND_RET_OK:

            qemu_aio_release(acb);

            // fall through

        case FIND_RET_WAIT:

            return;

        default:

            break;

    }



    // No cache found, so let's start a new request

    state = curl_init_state(s);

    if (!state) {

        acb->common.cb(acb->common.opaque, -EIO);

        qemu_aio_release(acb);

        return;

    }



    acb->start = 0;

    acb->end = (acb->nb_sectors * SECTOR_SIZE);



    state->buf_off = 0;

    g_free(state->orig_buf);

    state->buf_start = start;

    state->buf_len = acb->end + s->readahead_size;

    end = MIN(start + state->buf_len, s->len) - 1;

    state->orig_buf = g_malloc(state->buf_len);

    state->acb[0] = acb;



    snprintf(state->range, 127, "%zd-%zd", start, end);

    DPRINTF("CURL (AIO): Reading %d at %zd (%s)\n",

            (acb->nb_sectors * SECTOR_SIZE), start, state->range);

    curl_easy_setopt(state->curl, CURLOPT_RANGE, state->range);



    curl_multi_add_handle(s->multi, state->curl);



    /* Tell curl it needs to kick things off */

    curl_multi_socket_action(s->multi, CURL_SOCKET_TIMEOUT, 0, &running);

}

static int dnxhd_encode_rdo(AVCodecContext *avctx, DNXHDEncContext *ctx)

{

    int lambda, up_step, down_step;

    int last_lower = INT_MAX, last_higher = 0;

    int x, y, q;



    for (q = 1; q < avctx->qmax; q++) {

        ctx->qscale = q;

        avctx->execute2(avctx, dnxhd_calc_bits_thread, NULL, NULL, ctx->m.mb_height);

    }

    up_step = down_step = 2<<LAMBDA_FRAC_BITS;

    lambda = ctx->lambda;



    for (;;) {

        int bits = 0;

        int end = 0;

        if (lambda == last_higher) {

            lambda++;

            end = 1; // need to set final qscales/bits

        }

        for (y = 0; y < ctx->m.mb_height; y++) {

            for (x = 0; x < ctx->m.mb_width; x++) {

                unsigned min = UINT_MAX;

                int qscale = 1;

                int mb = y*ctx->m.mb_width+x;

                for (q = 1; q < avctx->qmax; q++) {

                    unsigned score = ctx->mb_rc[q][mb].bits*lambda+(ctx->mb_rc[q][mb].ssd<<LAMBDA_FRAC_BITS);

                    if (score < min) {

                        min = score;

                        qscale = q;

                    }

                }

                bits += ctx->mb_rc[qscale][mb].bits;

                ctx->mb_qscale[mb] = qscale;

                ctx->mb_bits[mb] = ctx->mb_rc[qscale][mb].bits;

            }

            bits = (bits+31)&~31; // padding

            if (bits > ctx->frame_bits)

                break;

        }

        //av_dlog(ctx->m.avctx, "lambda %d, up %u, down %u, bits %d, frame %d\n",

        //        lambda, last_higher, last_lower, bits, ctx->frame_bits);

        if (end) {

            if (bits > ctx->frame_bits)

                return -1;

            break;

        }

        if (bits < ctx->frame_bits) {

            last_lower = FFMIN(lambda, last_lower);

            if (last_higher != 0)

                lambda = (lambda+last_higher)>>1;

            else

                lambda -= down_step;

            down_step *= 5; // XXX tune ?

            up_step = 1<<LAMBDA_FRAC_BITS;

            lambda = FFMAX(1, lambda);

            if (lambda == last_lower)

                break;

        } else {

            last_higher = FFMAX(lambda, last_higher);

            if (last_lower != INT_MAX)

                lambda = (lambda+last_lower)>>1;

            else if ((int64_t)lambda + up_step > INT_MAX)

                return -1;

            else

                lambda += up_step;

            up_step = FFMIN((int64_t)up_step*5, INT_MAX);

            down_step = 1<<LAMBDA_FRAC_BITS;

        }

    }

    //av_dlog(ctx->m.avctx, "out lambda %d\n", lambda);

    ctx->lambda = lambda;

    return 0;

}

static int find_and_decode_index(NUTContext *nut)

{

    AVFormatContext *s = nut->avf;

    AVIOContext *bc    = s->pb;

    uint64_t tmp, end;

    int i, j, syncpoint_count;

    int64_t filesize = avio_size(bc);

    int64_t *syncpoints;

    int8_t *has_keyframe;

    int ret = AVERROR_INVALIDDATA;



    avio_seek(bc, filesize - 12, SEEK_SET);

    avio_seek(bc, filesize - avio_rb64(bc), SEEK_SET);

    if (avio_rb64(bc) != INDEX_STARTCODE) {

        av_log(s, AV_LOG_ERROR, "no index at the end\n");

        return ret;

    }



    end  = get_packetheader(nut, bc, 1, INDEX_STARTCODE);

    end += avio_tell(bc);



    ffio_read_varlen(bc); // max_pts

    GET_V(syncpoint_count, tmp < INT_MAX / 8 && tmp > 0);

    syncpoints   = av_malloc(sizeof(int64_t) *  syncpoint_count);

    has_keyframe = av_malloc(sizeof(int8_t)  * (syncpoint_count + 1));

    if (!syncpoints || !has_keyframe)

        return AVERROR(ENOMEM);

    for (i = 0; i < syncpoint_count; i++) {

        syncpoints[i] = ffio_read_varlen(bc);

        if (syncpoints[i] <= 0)

            goto fail;

        if (i)

            syncpoints[i] += syncpoints[i - 1];

    }



    for (i = 0; i < s->nb_streams; i++) {

        int64_t last_pts = -1;

        for (j = 0; j < syncpoint_count;) {

            uint64_t x = ffio_read_varlen(bc);

            int type   = x & 1;

            int n      = j;

            x >>= 1;

            if (type) {

                int flag = x & 1;

                x >>= 1;

                if (n + x >= syncpoint_count + 1) {

                    av_log(s, AV_LOG_ERROR, "index overflow A\n");

                    goto fail;

                }

                while (x--)

                    has_keyframe[n++] = flag;

                has_keyframe[n++] = !flag;

            } else {

                while (x != 1) {

                    if (n >= syncpoint_count + 1) {

                        av_log(s, AV_LOG_ERROR, "index overflow B\n");

                        goto fail;

                    }

                    has_keyframe[n++] = x & 1;

                    x >>= 1;

                }

            }

            if (has_keyframe[0]) {

                av_log(s, AV_LOG_ERROR, "keyframe before first syncpoint in index\n");

                goto fail;

            }

            assert(n <= syncpoint_count + 1);

            for (; j < n && j < syncpoint_count; j++) {

                if (has_keyframe[j]) {

                    uint64_t B, A = ffio_read_varlen(bc);

                    if (!A) {

                        A = ffio_read_varlen(bc);

                        B = ffio_read_varlen(bc);

                        // eor_pts[j][i] = last_pts + A + B

                    } else

                        B = 0;

                    av_add_index_entry(s->streams[i], 16 * syncpoints[j - 1],

                                       last_pts + A, 0, 0, AVINDEX_KEYFRAME);

                    last_pts += A + B;

                }

            }

        }

    }



    if (skip_reserved(bc, end) || ffio_get_checksum(bc)) {

        av_log(s, AV_LOG_ERROR, "index checksum mismatch\n");

        goto fail;

    }

    ret = 0;



fail:

    av_free(syncpoints);

    av_free(has_keyframe);

    return ret;

}

