static int decode_sgirle8(AVCodecContext *avctx, uint8_t *dst, const uint8_t *src, int src_size, int width, int height, int linesize)

{

    const uint8_t *src_end = src + src_size;

    int x = 0, y = 0;



#define INC_XY(n) \

    x += n; \

    if (x >= width) { \

        y++; \

        if (y >= height) \

            return 0; \

        x = 0; \

    }



    while (src_end - src >= 2) {

        uint8_t v = *src++;

        if (v > 0 && v < 0xC0) {

            do {

                int length = FFMIN(v, width - x);

                memset(dst + y*linesize + x, RGB332_TO_BGR8(*src), length);

                INC_XY(length);

                v   -= length;

            } while (v > 0);

            src++;

        } else if (v >= 0xC1) {

            v -= 0xC0;

            do {

                int length = FFMIN3(v, width - x, src_end - src);

                if (src_end - src < length)

                    break;

                memcpy_rgb332_to_bgr8(dst + y*linesize + x, src, length);

                INC_XY(length);

                src += length;

                v   -= length;

            } while (v > 0);

        } else {

            avpriv_request_sample(avctx, "opcode %d", v);

            return AVERROR_PATCHWELCOME;

        }

    }

    return 0;

}

static int hls_read_seek(AVFormatContext *s, int stream_index,

                               int64_t timestamp, int flags)

{

    HLSContext *c = s->priv_data;

    int i;

    int64_t seek_timestamp;

    int valid_for = -1;



    if ((flags & AVSEEK_FLAG_BYTE) || !c->variants[0]->playlists[0]->finished)

        return AVERROR(ENOSYS);



    seek_timestamp = stream_index < 0 ? timestamp :

                     av_rescale_rnd(timestamp, AV_TIME_BASE,

                                    s->streams[stream_index]->time_base.den,

                                    flags & AVSEEK_FLAG_BACKWARD ?

                                    AV_ROUND_DOWN : AV_ROUND_UP);



    if (s->duration < seek_timestamp)

        return AVERROR(EIO);



    for (i = 0; i < c->n_playlists; i++) {

        /* check first that the timestamp is valid for some playlist */

        struct playlist *pls = c->playlists[i];

        int seq_no;

        if (find_timestamp_in_playlist(c, pls, seek_timestamp, &seq_no)) {

            /* set segment now so we do not need to search again below */

            pls->cur_seq_no = seq_no;

            valid_for = i;

            break;

        }

    }



    if (valid_for < 0)

        return AVERROR(EIO);



    for (i = 0; i < c->n_playlists; i++) {

        /* Reset reading */

        struct playlist *pls = c->playlists[i];

        if (pls->input) {

            ffurl_close(pls->input);

            pls->input = NULL;

        }

        av_free_packet(&pls->pkt);

        reset_packet(&pls->pkt);

        pls->pb.eof_reached = 0;

        /* Clear any buffered data */

        pls->pb.buf_end = pls->pb.buf_ptr = pls->pb.buffer;

        /* Reset the pos, to let the mpegts demuxer know we've seeked. */

        pls->pb.pos = 0;



        pls->seek_timestamp = seek_timestamp;

        pls->seek_flags = flags;



        /* set closest segment seq_no for playlists not handled above */

        if (valid_for != i)

            find_timestamp_in_playlist(c, pls, seek_timestamp, &pls->cur_seq_no);

    }



    c->cur_timestamp = seek_timestamp;



    return 0;

}

static int assigned_initfn(struct PCIDevice *pci_dev)

{

    AssignedDevice *dev = DO_UPCAST(AssignedDevice, dev, pci_dev);

    uint8_t e_intx;

    int r;

    Error *local_err = NULL;



    if (!kvm_enabled()) {

        error_report("pci-assign: error: requires KVM support");

        return -1;

    }



    if (!dev->host.domain && !dev->host.bus && !dev->host.slot &&

        !dev->host.function) {

        error_report("pci-assign: error: no host device specified");

        return -1;

    }



    /*

     * Set up basic config space access control. Will be further refined during

     * device initialization.

     */

    assigned_dev_emulate_config_read(dev, 0, PCI_CONFIG_SPACE_SIZE);

    assigned_dev_direct_config_read(dev, PCI_STATUS, 2);

    assigned_dev_direct_config_read(dev, PCI_REVISION_ID, 1);

    assigned_dev_direct_config_read(dev, PCI_CLASS_PROG, 3);

    assigned_dev_direct_config_read(dev, PCI_CACHE_LINE_SIZE, 1);

    assigned_dev_direct_config_read(dev, PCI_LATENCY_TIMER, 1);

    assigned_dev_direct_config_read(dev, PCI_BIST, 1);

    assigned_dev_direct_config_read(dev, PCI_CARDBUS_CIS, 4);

    assigned_dev_direct_config_read(dev, PCI_SUBSYSTEM_VENDOR_ID, 2);

    assigned_dev_direct_config_read(dev, PCI_SUBSYSTEM_ID, 2);

    assigned_dev_direct_config_read(dev, PCI_CAPABILITY_LIST + 1, 7);

    assigned_dev_direct_config_read(dev, PCI_MIN_GNT, 1);

    assigned_dev_direct_config_read(dev, PCI_MAX_LAT, 1);

    memcpy(dev->emulate_config_write, dev->emulate_config_read,

           sizeof(dev->emulate_config_read));



    get_real_device(dev, &local_err);

    if (local_err) {

        qerror_report_err(local_err);

        error_free(local_err);

        goto out;

    }



    if (assigned_device_pci_cap_init(pci_dev, &local_err) < 0) {

        qerror_report_err(local_err);

        error_free(local_err);

        goto out;

    }



    /* intercept MSI-X entry page in the MMIO */

    if (dev->cap.available & ASSIGNED_DEVICE_CAP_MSIX) {

        assigned_dev_register_msix_mmio(dev, &local_err);

        if (local_err) {

            qerror_report_err(local_err);

            error_free(local_err);

            goto out;

        }

    }



    /* handle real device's MMIO/PIO BARs */

    assigned_dev_register_regions(dev->real_device.regions,

                                  dev->real_device.region_number, dev,

                                  &local_err);

    if (local_err) {

        qerror_report_err(local_err);

        error_free(local_err);

        goto out;

    }



    /* handle interrupt routing */

    e_intx = dev->dev.config[PCI_INTERRUPT_PIN] - 1;

    dev->intpin = e_intx;

    dev->intx_route.mode = PCI_INTX_DISABLED;

    dev->intx_route.irq = -1;



    /* assign device to guest */

    r = assign_device(dev);

    if (r < 0) {

        goto out;

    }



    /* assign legacy INTx to the device */

    r = assign_intx(dev);

    if (r < 0) {

        goto assigned_out;

    }



    assigned_dev_load_option_rom(dev);



    add_boot_device_path(dev->bootindex, &pci_dev->qdev, NULL);



    return 0;



assigned_out:

    deassign_device(dev);

out:

    free_assigned_device(dev);

    return -1;

}

