int kvm_arch_get_registers(CPUState *cs)

{

    S390CPU *cpu = S390_CPU(cs);

    CPUS390XState *env = &cpu->env;

    struct kvm_one_reg reg;

    struct kvm_sregs sregs;

    struct kvm_regs regs;

    int i, r;



    /* get the PSW */

    env->psw.addr = cs->kvm_run->psw_addr;

    env->psw.mask = cs->kvm_run->psw_mask;



    /* the GPRS */

    if (cap_sync_regs && cs->kvm_run->kvm_valid_regs & KVM_SYNC_GPRS) {

        for (i = 0; i < 16; i++) {

            env->regs[i] = cs->kvm_run->s.regs.gprs[i];

        }

    } else {

        r = kvm_vcpu_ioctl(cs, KVM_GET_REGS, &regs);

        if (r < 0) {

            return r;

        }

         for (i = 0; i < 16; i++) {

            env->regs[i] = regs.gprs[i];

        }

    }



    /* The ACRS and CRS */

    if (cap_sync_regs &&

        cs->kvm_run->kvm_valid_regs & KVM_SYNC_ACRS &&

        cs->kvm_run->kvm_valid_regs & KVM_SYNC_CRS) {

        for (i = 0; i < 16; i++) {

            env->aregs[i] = cs->kvm_run->s.regs.acrs[i];

            env->cregs[i] = cs->kvm_run->s.regs.crs[i];

        }

    } else {

        r = kvm_vcpu_ioctl(cs, KVM_GET_SREGS, &sregs);

        if (r < 0) {

            return r;

        }

         for (i = 0; i < 16; i++) {

            env->aregs[i] = sregs.acrs[i];

            env->cregs[i] = sregs.crs[i];

        }

    }



    /* The prefix */

    if (cap_sync_regs && cs->kvm_run->kvm_valid_regs & KVM_SYNC_PREFIX) {

        env->psa = cs->kvm_run->s.regs.prefix;

    }



    /* One Regs */

    reg.id = KVM_REG_S390_CPU_TIMER;

    reg.addr = (__u64)&(env->cputm);

    r = kvm_vcpu_ioctl(cs, KVM_GET_ONE_REG, &reg);

    if (r < 0) {

        return r;

    }



    reg.id = KVM_REG_S390_CLOCK_COMP;

    reg.addr = (__u64)&(env->ckc);

    r = kvm_vcpu_ioctl(cs, KVM_GET_ONE_REG, &reg);

    if (r < 0) {

        return r;

    }



    reg.id = KVM_REG_S390_TODPR;

    reg.addr = (__u64)&(env->todpr);

    r = kvm_vcpu_ioctl(cs, KVM_GET_ONE_REG, &reg);

    if (r < 0) {

        return r;

    }



    if (cap_async_pf) {

        reg.id = KVM_REG_S390_PFTOKEN;

        reg.addr = (__u64)&(env->pfault_token);

        r = kvm_vcpu_ioctl(cs, KVM_GET_ONE_REG, &reg);

        if (r < 0) {

            return r;

        }



        reg.id = KVM_REG_S390_PFCOMPARE;

        reg.addr = (__u64)&(env->pfault_compare);

        r = kvm_vcpu_ioctl(cs, KVM_GET_ONE_REG, &reg);

        if (r < 0) {

            return r;

        }



        reg.id = KVM_REG_S390_PFSELECT;

        reg.addr = (__u64)&(env->pfault_select);

        r = kvm_vcpu_ioctl(cs, KVM_GET_ONE_REG, &reg);

        if (r < 0) {

            return r;

        }

    }



    return 0;

}

int select_watchdog(const char *p)

{

    WatchdogTimerModel *model;

    QemuOpts *opts;



    /* -watchdog ? lists available devices and exits cleanly. */

    if (strcmp(p, "?") == 0) {

        LIST_FOREACH(model, &watchdog_list, entry) {

            fprintf(stderr, "\t%s\t%s\n",

                     model->wdt_name, model->wdt_description);

        }

        return 2;

    }



    LIST_FOREACH(model, &watchdog_list, entry) {

        if (strcasecmp(model->wdt_name, p) == 0) {

            /* add the device */

            opts = qemu_opts_create(&qemu_device_opts, NULL, 0);

            qemu_opt_set(opts, "driver", p);

            return 0;

        }

    }



    fprintf(stderr, "Unknown -watchdog device. Supported devices are:\n");

    LIST_FOREACH(model, &watchdog_list, entry) {

        fprintf(stderr, "\t%s\t%s\n",

                 model->wdt_name, model->wdt_description);

    }

    return 1;

}

static void virtio_balloon_handle_output(VirtIODevice *vdev, VirtQueue *vq)

{

    VirtIOBalloon *s = VIRTIO_BALLOON(vdev);

    VirtQueueElement elem;

    MemoryRegionSection section;



    while (virtqueue_pop(vq, &elem)) {

        size_t offset = 0;

        uint32_t pfn;



        while (iov_to_buf(elem.out_sg, elem.out_num, offset, &pfn, 4) == 4) {

            ram_addr_t pa;

            ram_addr_t addr;

            int p = virtio_ldl_p(vdev, &pfn);



            pa = (ram_addr_t) p << VIRTIO_BALLOON_PFN_SHIFT;

            offset += 4;



            /* FIXME: remove get_system_memory(), but how? */

            section = memory_region_find(get_system_memory(), pa, 1);

            if (!int128_nz(section.size) || !memory_region_is_ram(section.mr))

                continue;



            trace_virtio_balloon_handle_output(memory_region_name(section.mr),

                                               pa);

            /* Using memory_region_get_ram_ptr is bending the rules a bit, but

               should be OK because we only want a single page.  */

            addr = section.offset_within_region;

            balloon_page(memory_region_get_ram_ptr(section.mr) + addr,

                         !!(vq == s->dvq));

            memory_region_unref(section.mr);

        }



        virtqueue_push(vq, &elem, offset);

        virtio_notify(vdev, vq);

    }

}

static av_cold int vorbis_decode_init(AVCodecContext *avccontext)

{

    vorbis_context *vc = avccontext->priv_data;

    uint8_t *headers   = avccontext->extradata;

    int headers_len    = avccontext->extradata_size;

    uint8_t *header_start[3];

    int header_len[3];

    GetBitContext *gb = &vc->gb;

    int hdr_type, ret;



    vc->avccontext = avccontext;

    ff_dsputil_init(&vc->dsp, avccontext);

    ff_fmt_convert_init(&vc->fmt_conv, avccontext);



    if (avccontext->request_sample_fmt == AV_SAMPLE_FMT_FLT) {

        avccontext->sample_fmt = AV_SAMPLE_FMT_FLT;

        vc->scale_bias = 1.0f;

    } else {

        avccontext->sample_fmt = AV_SAMPLE_FMT_S16;

        vc->scale_bias = 32768.0f;

    }



    if (!headers_len) {

        av_log(avccontext, AV_LOG_ERROR, "Extradata missing.\n");

        return AVERROR_INVALIDDATA;

    }



    if ((ret = avpriv_split_xiph_headers(headers, headers_len, 30, header_start, header_len)) < 0) {

        av_log(avccontext, AV_LOG_ERROR, "Extradata corrupt.\n");

        return ret;

    }



    init_get_bits(gb, header_start[0], header_len[0]*8);

    hdr_type = get_bits(gb, 8);

    if (hdr_type != 1) {

        av_log(avccontext, AV_LOG_ERROR, "First header is not the id header.\n");

        return AVERROR_INVALIDDATA;

    }

    if ((ret = vorbis_parse_id_hdr(vc))) {

        av_log(avccontext, AV_LOG_ERROR, "Id header corrupt.\n");

        vorbis_free(vc);

        return ret;

    }



    init_get_bits(gb, header_start[2], header_len[2]*8);

    hdr_type = get_bits(gb, 8);

    if (hdr_type != 5) {

        av_log(avccontext, AV_LOG_ERROR, "Third header is not the setup header.\n");

        vorbis_free(vc);

        return AVERROR_INVALIDDATA;

    }

    if ((ret = vorbis_parse_setup_hdr(vc))) {

        av_log(avccontext, AV_LOG_ERROR, "Setup header corrupt.\n");

        vorbis_free(vc);

        return ret;

    }



    if (vc->audio_channels > 8)

        avccontext->channel_layout = 0;

    else

        avccontext->channel_layout = ff_vorbis_channel_layouts[vc->audio_channels - 1];



    avccontext->channels    = vc->audio_channels;

    avccontext->sample_rate = vc->audio_samplerate;

    avccontext->frame_size  = FFMIN(vc->blocksize[0], vc->blocksize[1]) >> 2;



    avcodec_get_frame_defaults(&vc->frame);

    avccontext->coded_frame = &vc->frame;



    return 0;

}

static void blk_send(QEMUFile *f, BlkMigBlock * blk)

{

    int len;

    uint64_t flags = BLK_MIG_FLAG_DEVICE_BLOCK;



    if (block_mig_state.zero_blocks &&

        buffer_is_zero(blk->buf, BLOCK_SIZE)) {

        flags |= BLK_MIG_FLAG_ZERO_BLOCK;

    }



    /* sector number and flags */

    qemu_put_be64(f, (blk->sector << BDRV_SECTOR_BITS)

                     | flags);



    /* device name */

    len = strlen(bdrv_get_device_name(blk->bmds->bs));

    qemu_put_byte(f, len);

    qemu_put_buffer(f, (uint8_t *)bdrv_get_device_name(blk->bmds->bs), len);



    /* if a block is zero we need to flush here since the network

     * bandwidth is now a lot higher than the storage device bandwidth.

     * thus if we queue zero blocks we slow down the migration */

    if (flags & BLK_MIG_FLAG_ZERO_BLOCK) {

        qemu_fflush(f);

        return;

    }



    qemu_put_buffer(f, blk->buf, BLOCK_SIZE);

}

int64_t qmp_guest_fsfreeze_freeze(Error **err)

{

    int ret = 0, i = 0;

    FsMountList mounts;

    struct FsMount *mount;

    Error *local_err = NULL;

    int fd;



    slog("guest-fsfreeze called");



    execute_fsfreeze_hook(FSFREEZE_HOOK_FREEZE, &local_err);

    if (error_is_set(&local_err)) {

        error_propagate(err, local_err);

        return -1;

    }



    QTAILQ_INIT(&mounts);

    build_fs_mount_list(&mounts, &local_err);

    if (error_is_set(&local_err)) {

        error_propagate(err, local_err);

        return -1;

    }



    /* cannot risk guest agent blocking itself on a write in this state */

    ga_set_frozen(ga_state);



    QTAILQ_FOREACH(mount, &mounts, next) {

        fd = qemu_open(mount->dirname, O_RDONLY);

        if (fd == -1) {

            error_setg_errno(err, errno, "failed to open %s", mount->dirname);

            goto error;

        }



        /* we try to cull filesytems we know won't work in advance, but other

         * filesytems may not implement fsfreeze for less obvious reasons.

         * these will report EOPNOTSUPP. we simply ignore these when tallying

         * the number of frozen filesystems.

         *

         * any other error means a failure to freeze a filesystem we

         * expect to be freezable, so return an error in those cases

         * and return system to thawed state.

         */

        ret = ioctl(fd, FIFREEZE);

        if (ret == -1) {

            if (errno != EOPNOTSUPP) {

                error_setg_errno(err, errno, "failed to freeze %s",

                                 mount->dirname);

                close(fd);

                goto error;

            }

        } else {

            i++;

        }

        close(fd);

    }



    free_fs_mount_list(&mounts);

    return i;



error:

    free_fs_mount_list(&mounts);

    qmp_guest_fsfreeze_thaw(NULL);

    return 0;

}

