void cpsr_write(CPUARMState *env, uint32_t val, uint32_t mask,

                CPSRWriteType write_type)

{

    uint32_t changed_daif;



    if (mask & CPSR_NZCV) {

        env->ZF = (~val) & CPSR_Z;

        env->NF = val;

        env->CF = (val >> 29) & 1;

        env->VF = (val << 3) & 0x80000000;

    }

    if (mask & CPSR_Q)

        env->QF = ((val & CPSR_Q) != 0);

    if (mask & CPSR_T)

        env->thumb = ((val & CPSR_T) != 0);

    if (mask & CPSR_IT_0_1) {

        env->condexec_bits &= ~3;

        env->condexec_bits |= (val >> 25) & 3;

    }

    if (mask & CPSR_IT_2_7) {

        env->condexec_bits &= 3;

        env->condexec_bits |= (val >> 8) & 0xfc;

    }

    if (mask & CPSR_GE) {

        env->GE = (val >> 16) & 0xf;

    }



    /* In a V7 implementation that includes the security extensions but does

     * not include Virtualization Extensions the SCR.FW and SCR.AW bits control

     * whether non-secure software is allowed to change the CPSR_F and CPSR_A

     * bits respectively.

     *

     * In a V8 implementation, it is permitted for privileged software to

     * change the CPSR A/F bits regardless of the SCR.AW/FW bits.

     */

    if (write_type != CPSRWriteRaw && !arm_feature(env, ARM_FEATURE_V8) &&

        arm_feature(env, ARM_FEATURE_EL3) &&

        !arm_feature(env, ARM_FEATURE_EL2) &&

        !arm_is_secure(env)) {



        changed_daif = (env->daif ^ val) & mask;



        if (changed_daif & CPSR_A) {

            /* Check to see if we are allowed to change the masking of async

             * abort exceptions from a non-secure state.

             */

            if (!(env->cp15.scr_el3 & SCR_AW)) {

                qemu_log_mask(LOG_GUEST_ERROR,

                              "Ignoring attempt to switch CPSR_A flag from "

                              "non-secure world with SCR.AW bit clear\n");

                mask &= ~CPSR_A;

            }

        }



        if (changed_daif & CPSR_F) {

            /* Check to see if we are allowed to change the masking of FIQ

             * exceptions from a non-secure state.

             */

            if (!(env->cp15.scr_el3 & SCR_FW)) {

                qemu_log_mask(LOG_GUEST_ERROR,

                              "Ignoring attempt to switch CPSR_F flag from "

                              "non-secure world with SCR.FW bit clear\n");

                mask &= ~CPSR_F;

            }



            /* Check whether non-maskable FIQ (NMFI) support is enabled.

             * If this bit is set software is not allowed to mask

             * FIQs, but is allowed to set CPSR_F to 0.

             */

            if ((A32_BANKED_CURRENT_REG_GET(env, sctlr) & SCTLR_NMFI) &&

                (val & CPSR_F)) {

                qemu_log_mask(LOG_GUEST_ERROR,

                              "Ignoring attempt to enable CPSR_F flag "

                              "(non-maskable FIQ [NMFI] support enabled)\n");

                mask &= ~CPSR_F;

            }

        }

    }



    env->daif &= ~(CPSR_AIF & mask);

    env->daif |= val & CPSR_AIF & mask;



    if (write_type != CPSRWriteRaw &&

        (env->uncached_cpsr & CPSR_M) != CPSR_USER &&

        ((env->uncached_cpsr ^ val) & mask & CPSR_M)) {

        if (bad_mode_switch(env, val & CPSR_M)) {

            /* Attempt to switch to an invalid mode: this is UNPREDICTABLE.

             * We choose to ignore the attempt and leave the CPSR M field

             * untouched.

             */

            mask &= ~CPSR_M;

        } else {

            switch_mode(env, val & CPSR_M);

        }

    }

    mask &= ~CACHED_CPSR_BITS;

    env->uncached_cpsr = (env->uncached_cpsr & ~mask) | (val & mask);

}

static void vfio_probe_nvidia_bar0_quirk(VFIOPCIDevice *vdev, int nr)

{

    VFIOQuirk *quirk;

    VFIOConfigMirrorQuirk *mirror;



    if (!vfio_pci_is(vdev, PCI_VENDOR_ID_NVIDIA, PCI_ANY_ID) ||

        !vfio_is_vga(vdev) || nr != 0) {

        return;

    }



    quirk = g_malloc0(sizeof(*quirk));

    mirror = quirk->data = g_malloc0(sizeof(*mirror));

    mirror->mem = quirk->mem = g_malloc0(sizeof(MemoryRegion));

    quirk->nr_mem = 1;

    mirror->vdev = vdev;

    mirror->offset = 0x88000;

    mirror->bar = nr;



    memory_region_init_io(mirror->mem, OBJECT(vdev),

                          &vfio_nvidia_mirror_quirk, mirror,

                          "vfio-nvidia-bar0-88000-mirror-quirk",

                          PCIE_CONFIG_SPACE_SIZE);

    memory_region_add_subregion_overlap(&vdev->bars[nr].region.mem,

                                        mirror->offset, mirror->mem, 1);



    QLIST_INSERT_HEAD(&vdev->bars[nr].quirks, quirk, next);



    /* The 0x1800 offset mirror only seems to get used by legacy VGA */

    if (vdev->has_vga) {

        quirk = g_malloc0(sizeof(*quirk));

        mirror = quirk->data = g_malloc0(sizeof(*mirror));

        mirror->mem = quirk->mem = g_malloc0(sizeof(MemoryRegion));

        quirk->nr_mem = 1;

        mirror->vdev = vdev;

        mirror->offset = 0x1800;

        mirror->bar = nr;



        memory_region_init_io(mirror->mem, OBJECT(vdev),

                              &vfio_nvidia_mirror_quirk, mirror,

                              "vfio-nvidia-bar0-1800-mirror-quirk",

                              PCI_CONFIG_SPACE_SIZE);

        memory_region_add_subregion_overlap(&vdev->bars[nr].region.mem,

                                            mirror->offset, mirror->mem, 1);



        QLIST_INSERT_HEAD(&vdev->bars[nr].quirks, quirk, next);

    }



    trace_vfio_quirk_nvidia_bar0_probe(vdev->vbasedev.name);

}

static inline void gen_op_arith_compute_ov(DisasContext *ctx, TCGv arg0,

                                           TCGv arg1, TCGv arg2, int sub)

{

    TCGv t0 = tcg_temp_new();



