bool ftrace_init(void)

{

    char mount_point[PATH_MAX];

    char path[PATH_MAX];

    int debugfs_found;

    int trace_fd = -1;



    debugfs_found = find_mount(mount_point, "debugfs");

    if (debugfs_found) {

        snprintf(path, PATH_MAX, "%s/tracing/tracing_on", mount_point);

        trace_fd = open(path, O_WRONLY);

        if (trace_fd < 0) {

            if (errno == EACCES) {

                trace_marker_fd = open("/dev/null", O_WRONLY);

                if (trace_marker_fd != -1) {

                    return true;

                }

            }

            perror("Could not open ftrace 'tracing_on' file");

            return false;

        } else {

            if (write(trace_fd, "1", 1) < 0) {

                perror("Could not write to 'tracing_on' file");

                close(trace_fd);

                return false;

            }

            close(trace_fd);

        }

        snprintf(path, PATH_MAX, "%s/tracing/trace_marker", mount_point);

        trace_marker_fd = open(path, O_WRONLY);

        if (trace_marker_fd < 0) {

            perror("Could not open ftrace 'trace_marker' file");

            return false;

        }

    } else {

        fprintf(stderr, "debugfs is not mounted\n");

        return false;

    }



    return true;

}

yuv2rgba64_1_c_template(SwsContext *c, const int32_t *buf0,

                       const int32_t *ubuf[2], const int32_t *vbuf[2],

                       const int32_t *abuf0, uint16_t *dest, int dstW,

                       int uvalpha, int y, enum AVPixelFormat target, int hasAlpha, int eightbytes)

{

    const int32_t *ubuf0 = ubuf[0], *vbuf0 = vbuf[0];

    int i;

    int A1 = 0xffff<<14, A2= 0xffff<<14;



    if (uvalpha < 2048) {

        for (i = 0; i < ((dstW + 1) >> 1); i++) {

            int Y1 = (buf0[i * 2]    ) >> 2;

            int Y2 = (buf0[i * 2 + 1]) >> 2;

            int U  = (ubuf0[i] + (-128 << 11)) >> 2;

            int V  = (vbuf0[i] + (-128 << 11)) >> 2;

            int R, G, B;



            Y1 -= c->yuv2rgb_y_offset;

            Y2 -= c->yuv2rgb_y_offset;

            Y1 *= c->yuv2rgb_y_coeff;

            Y2 *= c->yuv2rgb_y_coeff;

            Y1 += 1 << 13;

            Y2 += 1 << 13;



            if (hasAlpha) {

                A1 = abuf0[i * 2    ] << 11;

                A2 = abuf0[i * 2 + 1] << 11;



                A1 += 1 << 13;

                A2 += 1 << 13;

            }



            R = V * c->yuv2rgb_v2r_coeff;

            G = V * c->yuv2rgb_v2g_coeff + U * c->yuv2rgb_u2g_coeff;

            B =                            U * c->yuv2rgb_u2b_coeff;



            output_pixel(&dest[0], av_clip_uintp2(R_B + Y1, 30) >> 14);

            output_pixel(&dest[1], av_clip_uintp2(  G + Y1, 30) >> 14);

            output_pixel(&dest[2], av_clip_uintp2(B_R + Y1, 30) >> 14);

            if (eightbytes) {

                output_pixel(&dest[3], av_clip_uintp2(A1      , 30) >> 14);

                output_pixel(&dest[4], av_clip_uintp2(R_B + Y2, 30) >> 14);

                output_pixel(&dest[5], av_clip_uintp2(  G + Y2, 30) >> 14);

                output_pixel(&dest[6], av_clip_uintp2(B_R + Y2, 30) >> 14);

                output_pixel(&dest[7], av_clip_uintp2(A2      , 30) >> 14);

                dest += 8;

            } else {

                output_pixel(&dest[3], av_clip_uintp2(R_B + Y2, 30) >> 14);

                output_pixel(&dest[4], av_clip_uintp2(  G + Y2, 30) >> 14);

                output_pixel(&dest[5], av_clip_uintp2(B_R + Y2, 30) >> 14);

                dest += 6;

            }

        }

    } else {

        const int32_t *ubuf1 = ubuf[1], *vbuf1 = vbuf[1];

        int A1 = 0xffff<<14, A2 = 0xffff<<14;

        for (i = 0; i < ((dstW + 1) >> 1); i++) {

            int Y1 = (buf0[i * 2]    ) >> 2;

            int Y2 = (buf0[i * 2 + 1]) >> 2;

            int U  = (ubuf0[i] + ubuf1[i] + (-128 << 12)) >> 3;

            int V  = (vbuf0[i] + vbuf1[i] + (-128 << 12)) >> 3;

            int R, G, B;



            Y1 -= c->yuv2rgb_y_offset;

            Y2 -= c->yuv2rgb_y_offset;

            Y1 *= c->yuv2rgb_y_coeff;

            Y2 *= c->yuv2rgb_y_coeff;

            Y1 += 1 << 13;

            Y2 += 1 << 13;



            if (hasAlpha) {

                A1 = abuf0[i * 2    ] << 11;

                A2 = abuf0[i * 2 + 1] << 11;



                A1 += 1 << 13;

                A2 += 1 << 13;

            }



            R = V * c->yuv2rgb_v2r_coeff;

            G = V * c->yuv2rgb_v2g_coeff + U * c->yuv2rgb_u2g_coeff;

            B =                            U * c->yuv2rgb_u2b_coeff;



            output_pixel(&dest[0], av_clip_uintp2(R_B + Y1, 30) >> 14);

            output_pixel(&dest[1], av_clip_uintp2(  G + Y1, 30) >> 14);

            output_pixel(&dest[2], av_clip_uintp2(B_R + Y1, 30) >> 14);

            if (eightbytes) {

                output_pixel(&dest[3], av_clip_uintp2(A1      , 30) >> 14);

                output_pixel(&dest[4], av_clip_uintp2(R_B + Y2, 30) >> 14);

                output_pixel(&dest[5], av_clip_uintp2(  G + Y2, 30) >> 14);

                output_pixel(&dest[6], av_clip_uintp2(B_R + Y2, 30) >> 14);

                output_pixel(&dest[7], av_clip_uintp2(A2      , 30) >> 14);

                dest += 8;

            } else {

                output_pixel(&dest[3], av_clip_uintp2(R_B + Y2, 30) >> 14);

                output_pixel(&dest[4], av_clip_uintp2(  G + Y2, 30) >> 14);

                output_pixel(&dest[5], av_clip_uintp2(B_R + Y2, 30) >> 14);

                dest += 6;

            }

        }

    }

}

